package com.multitenanterp.payroll;
import org.apache.pdfbox.pdmodel.*;import org.apache.pdfbox.pdmodel.common.PDRectangle;import org.apache.pdfbox.pdmodel.font.*;import org.springframework.stereotype.Component;import java.awt.Color;import java.io.*;import java.math.*;import java.time.Month;import java.time.format.TextStyle;import java.util.*;
@Component public class PayslipPdfGenerator{
 public byte[] generate(PayslipData d){try(var document=new PDDocument();var out=new ByteArrayOutputStream()){PDPage page=new PDPage(PDRectangle.A4);document.addPage(page);try(PDPageContentStream c=new PDPageContentStream(document,page)){PDFont regular=new PDType1Font(Standard14Fonts.FontName.HELVETICA),bold=new PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD);float left=48,right=547,y=790;c.setNonStrokingColor(new Color(30,55,82));c.addRect(0,742,595,100);c.fill();c.setNonStrokingColor(Color.WHITE);text(c,bold,18,255,804,clean(d.companyName()));text(c,regular,10,255,786,clean(d.companyAddress()));text(c,bold,15,left,758,"PAYSLIP - "+Month.of(d.month()).getDisplayName(TextStyle.FULL,Locale.ENGLISH).toUpperCase(Locale.ROOT)+" "+d.year());c.setNonStrokingColor(new Color(30,55,82));y=718;text(c,bold,10,left,y,"EMPLOYEE");text(c,regular,10,left,y-20,"Name: "+clean(d.employeeName()));text(c,regular,10,left,y-36,"Employee no: "+clean(d.employeeNumber()));text(c,regular,10,315,y-20,"Payable days: "+money(d.payableDays()));text(c,regular,10,315,y-36,"Period days: "+money(d.periodDays()));y=640;line(c,left,y,right,y);text(c,bold,10,left,y-18,"EARNINGS");text(c,bold,10,250,y-18,"AMOUNT");text(c,bold,10,315,y-18,"DEDUCTIONS");text(c,bold,10,500,y-18,"AMOUNT");y-=38;List<Item> earnings=d.items().stream().filter(x->x.type().equals("EARNING")).toList(),deductions=d.items().stream().filter(x->x.type().equals("DEDUCTION")).toList();int rows=Math.max(earnings.size(),deductions.size());for(int i=0;i<rows;i++,y-=18){if(i<earnings.size()){text(c,regular,9,left,y,clean(earnings.get(i).name()));right(c,regular,9,290,y,money(earnings.get(i).amount()));}if(i<deductions.size()){text(c,regular,9,315,y,clean(deductions.get(i).name()));right(c,regular,9,547,y,money(deductions.get(i).amount()));}}y-=8;line(c,left,y,right,y);y-=22;text(c,bold,10,left,y,"Gross earnings");right(c,bold,10,290,y,money(d.gross()));text(c,bold,10,315,y,"Total deductions");right(c,bold,10,547,y,money(d.deductions()));y-=48;c.setNonStrokingColor(new Color(234,242,248));c.addRect(left,y-12,right-left,38);c.fill();c.setNonStrokingColor(new Color(30,55,82));text(c,bold,13,left+12,y+2,"NET PAY");right(c,bold,13,right-12,y+2,"INR "+money(d.net()));c.setNonStrokingColor(new Color(80,80,80));text(c,regular,8,left,55,"System generated payslip. No signature is required.");right(c,regular,8,right,55,"Payslip ID: "+d.payslipId());}document.save(out);return out.toByteArray();}catch(IOException e){throw new IllegalStateException("Unable to generate payslip PDF",e);}}
 private static void text(PDPageContentStream c,PDFont f,float size,float x,float y,String value)throws IOException{c.beginText();c.setFont(f,size);c.newLineAtOffset(x,y);c.showText(value);c.endText();}private static void right(PDPageContentStream c,PDFont f,float size,float right,float y,String value)throws IOException{text(c,f,size,right-f.getStringWidth(value)/1000*size,y,value);}private static void line(PDPageContentStream c,float x1,float y1,float x2,float y2)throws IOException{c.setStrokingColor(new Color(190,200,210));c.moveTo(x1,y1);c.lineTo(x2,y2);c.stroke();}private static String money(BigDecimal v){return v.setScale(2,RoundingMode.HALF_UP).toPlainString();}private static String clean(String v){return v==null?"":v.replaceAll("[^\\x20-\\x7E]","?");}
 public record Item(String name,String type,BigDecimal amount){}public record PayslipData(UUID payslipId,String companyName,String companyAddress,String employeeNumber,String employeeName,int year,int month,BigDecimal periodDays,BigDecimal payableDays,BigDecimal gross,BigDecimal deductions,BigDecimal net,List<Item> items){}
}
